// Dynamic baseURL - return function so it's re-evaluated each time
export const getBaseURL = () => {
  try {
    const user = JSON.parse(localStorage.getItem(`_authUsr`));
    const country = localStorage.getItem('_country') || getInitialCountry(user);
    return getAPIEndpoint(country);
  } catch (error) {
    // Fallback to DRC API if there's an error
    return getAPIEndpoint('DRC');
  }
};

